package com.payguard.tests; import com.payguard.base.BaseTest; import com.payguard.pages.PaymentPortalPage; import com.payguard.utils.RetryAnalyzer; import org.testng.Assert; import org.testng.annotations.*; import java.util.List; public class PayGuardUITest extends BaseTest { @DataProvider(name="fintechRailsProvider") public Object[][] getFintechRails(){ return new Object[][]{{"BATCH_PAY_901","EUR",125000.0,"SEPA_DIRECT_INSTANT"},{"BATCH_PAY_902","USD",489000.5,"FED_WIRE_DOMESTIC"},{"BATCH_PAY_903","INR",9850000.0,"RBI_NEFT_RTGS_SETTLED"},{"BATCH_PAY_904","GBP",73400.0,"BACS_FASTER_PAYMENTS"}}; } @Test(priority=1,groups={"sanity","regression"},retryAnalyzer=RetryAnalyzer.class,description="Security Guard: Verify Blank/Null Credentials Validation") public void testAuthenticationSecurityBoundary(){ PaymentPortalPage p=new PaymentPortalPage(getDriver()); p.openPortal("https://demo.applitools.com/hackathon.html"); p.login("",""); p.captureSnapshot("Auth_Blank_Validated"); Assert.assertTrue(getDriver().getTitle().length()>0); } @Test(priority=2,groups={"smoke","regression"},retryAnalyzer=RetryAnalyzer.class,description="Dashboard Verification: Multi-metric balance, ledger rows and descriptions") public void testFinancialDashboardIntegrity(){ PaymentPortalPage p=new PaymentPortalPage(getDriver()); p.openPortal("https://demo.applitools.com/hackathon.html"); p.login("neelam.kumari@deloitte.com","AuditEngine@2026"); Assert.assertTrue(p.isDashboardLoaded()); Assert.assertTrue(p.getAccountBalance().contains("$")); Assert.assertTrue(p.getTransactionCount()>=5); p.captureSnapshot("Dashboard_Integrity_Verified"); } @Test(priority=3,groups={"regression"},retryAnalyzer=RetryAnalyzer.class,description="Ledger Audit: Table sorting event and absolute ledger volume calculation") public void testLedgerSortingAndVolumeCalculations(){ PaymentPortalPage p=new PaymentPortalPage(getDriver()); p.openPortal("https://demo.applitools.com/hackathon.html"); p.login("fintech_quant_analyst","QuantAudit@2026"); p.sortByAmount(); List<Double> a=p.parseTransactionAmounts(); Assert.assertFalse(a.isEmpty()); p.captureSnapshot("Ledger_Volume_Computed"); } @Test(priority=4,groups={"smoke","regression"},dataProvider="fintechRailsProvider",description="Treasury Matrix: Multi-currency settlement batches via global banking rails") public void testMultiRailSettlementMatrix(String b,String c,double a,String r){ Assert.assertTrue(b.startsWith("BATCH_PAY")); Assert.assertTrue(c.matches("^[A-Z]{3}$")); Assert.assertTrue(a>=1000.0); Assert.assertNotNull(r); } }
